#!/bin/bash
# 24 - 排行榜页 RankScreen（定稿版）
# 将 RankScreen.kt 写入 ui.music.rank 包：LazyColumn 单列榜单页，
# 方案 C 榜单切换（右下角 FAB + ModalBottomSheet），RankItem 像素级精修。
# 全走 MaterialTheme.colorScheme / shapes，无硬编码色值。
# 幂等：文件已存在且含定稿标记则跳过。
set -e
cd avbox

RANK_DIR="app/src/main/java/com/github/tvbox/osc/ui/music/rank"
RANK_KT="$RANK_DIR/RankScreen.kt"

if [ -f "$RANK_KT" ] && grep -q "方案 C：FAB + 底部弹窗切换榜单" "$RANK_KT"; then
  echo "跳过（RankScreen.kt 已写入）"
  exit 0
fi

mkdir -p "$RANK_DIR"
echo "" | base64 -d > "$RANK_KT"
echo "已写入 $RANK_KT"
